#include <iostream>

namespace ns { int v = 2; }

int main() {
    std::cout << "unqualified=";
    {
        using namespace ns;        // 块内局部引入，作用域可控
        std::cout << v;             // 未限定：ns::v 被 using 纳入候选 → 2
    }
    std::cout << " qualified=" << ns::v << '\n';   // 限定查找：始终命中 ns::v
}
